/*
 * A creation that points at a hand-in (`submission`) takes what it holds from that version, so a
 * hand-in's files are never stored twice (SCOPE R7). Anything else holds its own file, link or text.
 * The pointer is honoured only when the version and the step are the same learner's.
 * `estimate` (DBU-10): the hours a week she said she saves, from her LATEST answered 6-week impact
 * check-in (form id six-week-impact, question id hours_per_week), or null: none answered, or the
 * latest did not give hours ("Not really"). Her own estimate, shown as such.
 */
if (Inputs.learner !== undefined) {
  (async () => {
    try {
      const me = String(Inputs.learner || '');
      if (!me) throw new Error('no learner');
      const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });
      const when = (v) => (v && typeof v === 'object' && v.iso ? v.iso : v instanceof Date ? v.toISOString() : String(v || ''));
      const rows = await q('Creation', { learner: { equalTo: me } });
      const subIds = rows.map((r) => r.submission).filter(Boolean);
      const stepIds = rows.map((r) => r.fromStep).filter(Boolean);
      const subs = subIds.length ? await q('Submission', { objectId: { containedIn: subIds } }) : [];
      const steps = stepIds.length ? await q('Step', { objectId: { containedIn: stepIds } }) : [];
      Outputs.items = rows.map((c) => {
        const sub = c.submission ? subs.find((s) => s.objectId === c.submission && s.learner === me) : null;
        const step = c.fromStep ? steps.find((s) => s.objectId === c.fromStep && s.learner === me && s.shared === true) : null;
        let form = '';
        let files = [];
        let url = '';
        let text = '';
        if (sub) {
          form = sub.kind === 'file' ? 'file' : sub.kind;
          files = sub.kind === 'file' && Array.isArray(sub.files) ? sub.files.map((f) => ({ file: f.file, fileName: f.fileName })) : [];
          url = sub.kind === 'link' ? String(sub.url || '') : '';
          text = sub.kind === 'text' ? String(sub.text || '') : '';
        } else if (c.file) {
          form = 'file';
          files = [{ file: c.file, fileName: c.fileName || 'file' }];
        } else if (c.url) {
          form = 'link';
          url = String(c.url);
        } else if (c.text) {
          form = 'text';
          text = String(c.text);
        }
        return {
          id: c.objectId,
          title: c.title || '',
          kind: c.kind || 'other',
          form,
          files,
          url,
          text,
          madeWith: c.madeWith || '',
          description: c.description || '',
          usedInClass: c.usedInClass === true,
          fromHandIn: !!sub,
          version: sub ? Number(sub.version) || null : null,
          stepId: step ? step.objectId : '',
          stepTitle: step ? step.title || '' : '',
          createdAt: when(c.createdAt)
        };
      }).sort((a, b) => b.createdAt.localeCompare(a.createdAt));

      const impact = (await q('CheckinResponse', { learner: { equalTo: me } }))
        .filter((r) => r.form && r.form.id === 'six-week-impact')
        .sort((a, b) => when(b.createdAt).localeCompare(when(a.createdAt)))[0];
      const hours = impact && impact.answers ? Number(impact.answers.hours_per_week) : NaN;
      Outputs.estimate = impact && impact.answers && impact.answers.hours_per_week !== undefined && Number.isFinite(hours)
        ? { hours, at: when(impact.createdAt) }
        : null;
      Outputs.done();
    } catch (e) {
      console.error('[dbu:Creations of]', String((e && e.message) || e));
      Outputs.failed();
    }
  })();
}
